{
  "title": "破晓之森",
  "scene": "你站在一片蒙着薄雾的古老森林边缘，阳光穿透树冠，洒下斑驳的光影。四周静悄悄的，只有远处隐约传来的鸟鸣。你记得《山海经》中曾提到，这里居住着一只名为‘幽光兽’的异兽，它能指引迷路者通往正确的道路。但在它的巢穴前，必须先找到一块‘破晓石’，才能得到幽光兽的认可。",
  "goal": "找到破晓石，得到幽光兽的认可。",
  "clue": "破晓石隐藏在幽光兽巢穴附近的古树根部，线索埋在描述破晓之森的场景中。",
  "choices": [
    {"id": "A", "text": "寻找巢穴附近的古树根部", "outcome": "你看到了一块闪耀着微光的石头，正是破晓石。幽光兽对你发出了轻微的叫声，似乎认可了你。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "四处寻找，试图吸引幽光兽", "outcome": "你四处寻找，声音渐大，但没有发现幽光兽的踪迹。最终，你累得坐在树下休息，错过了破晓石的机会。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "继续深入森林，探索未知的区域", "outcome": "你深入森林，但迷失了方向。四周的环境变得越来越难以辨认，最终你迷路了。", "result": "fail", "next": "retry"}
  ]
}
